        fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
      };

      await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
        "fetch failed",
      );
    });
  });

  describe("with InventoryChecker", () => {
    it("passes when all items are available", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);

      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };

      const result = await cart.checkout({ inventoryChecker: checker });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(checker.check).toHaveBeenCalledWith("a", 2);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);

      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 0,
          reason: "out of stock",
        }),
      };

      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(2);
        expect(err.available).toBe(0);
        expect(err.message).toBe("out of stock");
      }
    });

    it("throws InventoryError for partial-stock denial (availableQuantity < requested)", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 5);

      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };

      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(5);
        expect(err.available).toBe(3);
      }
    });

    it("first denial wins when multiple items fail", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      cart.add(product("b", 2000), 1);

      const checker: InventoryChecker = {
        check: vi.fn()
          .mockResolvedValueOnce({ available: false, reason: "no stock a" })
          .mockResolvedValueOnce({ available: false, reason: "no stock b" }),
      };

      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        // Only first item checked before throwing
        expect(checker.check).toHaveBeenCalledTimes(1);
      }
    });

    it("uses default message when reason is not provided", async () => {
      const cart = new Cart();
      cart.add(product("x", 1000), 3);

      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: false }),
      };

      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.message).toContain("insufficient stock");
        expect(err.message).toContain("x");
      }
    });
  });

  describe("with AsyncTaxRateProvider", () => {
    it("uses async tax instead of sync tax calculator", async () => {
      const cart = new Cart();
      cart.add(product("a", 10000), 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.08),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      // 8% of 10000 = 800
      expect(result.totals.taxCents).toBe(800);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
    });

    it("propagates async tax provider failure", async () => {
      const cart = new Cart();
      cart.add(product("a", 5000), 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service down",
      );
    });

    it("applies discount before async tax", async () => {
      const discount: DiscountPolicy = { computeDiscountCents: () => 2000 };
      const cart = new Cart({ discountPolicy: discount });
      cart.add(product("a", 10000), 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      // subtotal=10000, discount=2000, discounted=8000, tax=800
      expect(result.totals.discountCents).toBe(2000);
      expect(result.totals.taxCents).toBe(800);
    });

    it("includes shipping in async totals", async () => {
      const shipping: ShippingCalculator = {
        computeShippingCents: () => 599,
      };
      const cart = new Cart({ shippingCalculator: shipping });
      cart.add(product("a", 5000), 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      expect(result.totals.shippingCents).toBe(599);
      expect(result.totals.totalCents).toBe(5599);
    });
  });

  describe("full pipeline with all collaborators", () => {
    it("refreshes prices, checks inventory, then computes async totals", async () => {
      const discount: DiscountPolicy = { computeDiscountCents: (s) => Math.floor(s * 0.1) };
      const shipping: ShippingCalculator = { computeShippingCents: () => 500 };
      const cart = new Cart({
        discountPolicy: discount,
        shippingCalculator: shipping,
        region: "US-CA",
      });
      cart.add(product("a", 1000), 2);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1200),
      };
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.0875),
      };

      const result = await cart.checkout({
        priceFetcher: fetcher,
        inventoryChecker: checker,
        asyncTaxProvider,
      });

      // refreshed price: 1200 * 2 = 2400
      expect(result.totals.subtotalCents).toBe(2400);
      // discount: 10% of 2400 = 240
      expect(result.totals.discountCents).toBe(240);
      // discounted = 2160, tax = 8.75% of 2160 = 189.0 → 189
      expect(result.totals.taxCents).toBe(189);
      expect(result.totals.shippingCents).toBe(500);
      // total = 2160 + 189 + 500 = 2849
      expect(result.totals.totalCents).toBe(2849);

      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
      expect(checker.check).toHaveBeenCalledWith("a", 2);
    });
  });
});

