describe("WeightBasedShippingCalculator", () => {
  it("rejects empty brackets", () => {
    expect(() => new WeightBasedShippingCalculator([])).toThrow(
      "at least one weight bracket is required",
    );
  });

  it("rejects bracket with non-positive upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 500 }]),
    ).toThrow(RangeError);
  });

  it("rejects bracket with negative costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
    ).toThrow(RangeError);
  });

  it("rejects negative overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 1000, costCents: 500 }],
          -1,
        ),
    ).toThrow(RangeError);
  });

  it("rejects non-integer overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 1000, costCents: 500 }],
          10.5,
        ),
    ).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([], 5000)).toBe(0);
  });

  it("returns 0 when total weight is 0 (no weightGrams)", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", undefined, 2)], 5000)).toBe(0);
  });

  it("selects the first bracket whose upToGrams >= weight", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ]);
    // 400g → first bracket
    expect(calc.computeShippingCents([makeLine("a", 400, 1)], 5000)).toBe(300);
    // 500g → first bracket (boundary)
    expect(calc.computeShippingCents([makeLine("a", 500, 1)], 5000)).toBe(300);
    // 501g → second bracket
    expect(calc.computeShippingCents([makeLine("a", 501, 1)], 5000)).toBe(600);
    // 1000g → second bracket (boundary)
    expect(calc.computeShippingCents([makeLine("a", 1000, 1)], 5000)).toBe(600);
    // 1001g → third bracket
    expect(calc.computeShippingCents([makeLine("a", 1001, 1)], 5000)).toBe(1200);
  });

  it("sorts brackets regardless of input order", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 5000, costCents: 1200 },
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 400, 1)], 5000)).toBe(300);
    expect(calc.computeShippingCents([makeLine("a", 900, 1)], 5000)).toBe(600);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ],
      2000,
    );
    expect(calc.computeShippingCents([makeLine("a", 1500, 1)], 5000)).toBe(2000);
  });

  it("falls back to heaviest bracket cost when no overflow specified", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 5000, 1)], 5000)).toBe(600);
  });

  it("sums weight across multiple lines", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 2000, costCents: 900 },
    ]);
    // 300*2 + 500*1 = 1100 → second bracket
    const lines: CartLine[] = [makeLine("a", 300, 2), makeLine("b", 500, 1)];
    expect(calc.computeShippingCents(lines, 5000)).toBe(900);
  });
});

import { describe, it, expect } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const product = (id: string, unitPriceCents: number, weightGrams?: number): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents,
  weightGrams,
});

describe("Cart — line management", () => {
  it("starts empty with 0 items and 0 totals", () => {
    const cart = new Cart();
    expect(cart.itemCount).toBe(0);
    const t = cart.totals();
    expect(t.subtotalCents).toBe(0);
    expect(t.totalCents).toBe(0);
  });

  it("adds a product", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    expect(cart.itemCount).toBe(2);
  });

  it("merges quantity when adding the same product again", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    cart.add(product("a", 1000), 3);
    expect(cart.itemCount).toBe(5);
  });

  it("rejects non-positive quantity in add", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a", 1000), 0)).toThrow(RangeError);
    expect(() => cart.add(product("a", 1000), -1)).toThrow(RangeError);
    expect(() => cart.add(product("a", 1000), 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents in add", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
  });

  it("removes a product and returns true", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("unknown")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 3);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the item", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("unknown", 5)).toThrow();
  });

  it("clear removes all items", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    cart.add(product("b", 2000), 2);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy (mutations don't affect cart)", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const snap = cart.snapshot();
    (snap as any)[0].quantity = 99;
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart — pricing pipeline", () => {
  it("subtotal is sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    cart.add(product("b", 500), 3);
    expect(cart.totals().subtotalCents).toBe(3500);
  });

  it("applies discount from injected policy", () => {
    const discount: DiscountPolicy = { computeDiscountCents: () => 500 };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(product("a", 2000), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(500);
    expect(t.totalCents).toBe(1500);
  });

  it("clamps discount to [0, subtotal]", () => {
    const overDiscount: DiscountPolicy = { computeDiscountCents: () => 99999 };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(product("a", 1000), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(1000);
    expect(t.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const negDiscount: DiscountPolicy = { computeDiscountCents: () => -500 };
    const cart = new Cart({ discountPolicy: negDiscount });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("tax is computed on discounted subtotal", () => {
    const discount: DiscountPolicy = { computeDiscountCents: () => 200 };
    const tax: TaxCalculator = {
      computeTaxCents: (taxable, _region) => Math.floor(taxable * 0.1),
    };
    const cart = new Cart({ discountPolicy: discount, taxCalculator: tax });
    cart.add(product("a", 1000), 1);
    // subtotal=1000, discount=200, discounted=800, tax=80
    const t = cart.totals();
    expect(t.taxCents).toBe(80);
  });

  it("shipping receives discounted subtotal", () => {
    const discount: DiscountPolicy = { computeDiscountCents: () => 500 };
    const shipping: ShippingCalculator = {
      computeShippingCents: (_lines, subtotalCents) =>
        subtotalCents >= 1000 ? 0 : 500,
    };
    const cart = new Cart({ discountPolicy: discount, shippingCalculator: shipping });
    cart.add(product("a", 1200), 1);
    // discounted = 700, which is < 1000, so shipping = 500
    expect(cart.totals().shippingCents).toBe(500);
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const discount: DiscountPolicy = { computeDiscountCents: () => 100 };
    const tax: TaxCalculator = { computeTaxCents: () => 50 };
    const shipping: ShippingCalculator = { computeShippingCents: () => 200 };
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
    });
    cart.add(product("a", 1000), 1);
    // subtotal=1000, discount=100, discounted=900, tax=50, ship=200
    // total = 900 + 50 + 200 = 1150
    const t = cart.totals();
    expect(t.totalCents).toBe(1150);
  });

  it("uses default region US", () => {
    let receivedRegion = "";
    const tax: TaxCalculator = {
      computeTaxCents: (_taxable, region) => {
        receivedRegion = region;
        return 0;
      },
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(product("a", 1000), 1);
    cart.totals();
    expect(receivedRegion).toBe("US");
  });

  it("uses custom region when configured", () => {
    let receivedRegion = "";
    const tax: TaxCalculator = {
      computeTaxCents: (_taxable, region) => {
        receivedRegion = region;
        return 0;
      },
    };
    const cart = new Cart({ taxCalculator: tax, region: "FR" });
    cart.add(product("a", 1000), 1);
    cart.totals();
    expect(receivedRegion).toBe("FR");
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const product = (id: string, unitPriceCents: number): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents,
});

describe("Cart.checkout()", () => {
  describe("without collaborators", () => {
    it("returns totals based on current lines", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0].quantity).toBe(2);
    });
  });

  describe("with PriceFetcher", () => {
    it("refreshes prices before computing totals", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };

      const result = await cart.checkout({ priceFetcher: fetcher });
      expect(result.totals.subtotalCents).toBe(1500);
      expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    });

    it("throws RangeError when fetcher returns invalid price", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(-5),
      };

      await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
        RangeError,
      );
    });

    it("throws RangeError when fetcher returns non-integer price", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(10.5),
      };

      await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
        RangeError,
      );
    });

    it("propagates fetcher rejection", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
      };

      await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
        "fetch failed",
      );
    });
  });

  describe("with InventoryChecker", () => {
    it("passes when all items are available", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);

      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };

      const result = await cart.checkout({ inventoryChecker: checker });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(checker.check).toHaveBeenCalledWith("a", 2);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);

      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 0,
          reason: "out of stock",
        }),
      };

      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(2);
        expect(err.available).toBe(0);
        expect(err.message).toBe("out of stock");
      }
    });

    it("throws InventoryError for partial-stock denial (availableQuantity < requested)", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 5);

      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };

      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(5);
        expect(err.available).toBe(3);
      }
    });

    it("first denial wins when multiple items fail", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      cart.add(product("b", 2000), 1);

      const checker: InventoryChecker = {
        check: vi.fn()
          .mockResolvedValueOnce({ available: false, reason: "no stock a" })
          .mockResolvedValueOnce({ available: false, reason: "no stock b" }),
      };

      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        // Only first item checked before throwing
        expect(checker.check).toHaveBeenCalledTimes(1);
      }
    });

    it("uses default message when reason is not provided", async () => {
      const cart = new Cart();
      cart.add(product("x", 1000), 3);

      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: false }),
      };

      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.message).toContain("insufficient stock");
        expect(err.message).toContain("x");
      }
    });
  });

  describe("with AsyncTaxRateProvider", () => {
    it("uses async tax instead of sync tax calculator", async () => {
      const cart = new Cart();
      cart.add(product("a", 10000), 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.08),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      // 8% of 10000 = 800
      expect(result.totals.taxCents).toBe(800);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
    });

    it("propagates async tax provider failure", async () => {
      const cart = new Cart();
      cart.add(product("a", 5000), 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service down",
      );
    });

    it("applies discount before async tax", async () => {
      const discount: DiscountPolicy = { computeDiscountCents: () => 2000 };
      const cart = new Cart({ discountPolicy: discount });
      cart.add(product("a", 10000), 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      // subtotal=10000, discount=2000, discounted=8000, tax=800
      expect(result.totals.discountCents).toBe(2000);
      expect(result.totals.taxCents).toBe(800);
    });

    it("includes shipping in async totals", async () => {
      const shipping: ShippingCalculator = {
        computeShippingCents: () => 599,
      };
      const cart = new Cart({ shippingCalculator: shipping });
      cart.add(product("a", 5000), 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      expect(result.totals.shippingCents).toBe(599);
      expect(result.totals.totalCents).toBe(5599);
    });
  });

  describe("full pipeline with all collaborators", () => {
    it("refreshes prices, checks inventory, then computes async totals", async () => {
      const discount: DiscountPolicy = { computeDiscountCents: (s) => Math.floor(s * 0.1) };
      const shipping: ShippingCalculator = { computeShippingCents: () => 500 };
      const cart = new Cart({
        discountPolicy: discount,
        shippingCalculator: shipping,
        region: "US-CA",
      });
      cart.add(product("a", 1000), 2);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1200),
      };
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.0875),
      };

      const result = await cart.checkout({
        priceFetcher: fetcher,
        inventoryChecker: checker,
        asyncTaxProvider,
      });

      // refreshed price: 1200 * 2 = 2400
      expect(result.totals.subtotalCents).toBe(2400);
      // discount: 10% of 2400 = 240
      expect(result.totals.discountCents).toBe(240);
      // discounted = 2160, tax = 8.75% of 2160 = 189.0 → 189
      expect(result.totals.taxCents).toBe(189);
      expect(result.totals.shippingCents).toBe(500);
      // total = 2160 + 189 + 500 = 2849
      expect(result.totals.totalCents).toBe(2849);

      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
      expect(checker.check).toHaveBeenCalledWith("a", 2);
    });
  });
});

