describe("CompositeDiscountPolicy", () => {
  it("rejects an empty policy list", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow(
      "CompositeDiscountPolicy requires at least one policy",
    );
  });

  describe("sum mode", () => {
    it("sums discounts from multiple policies", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 10000 = 1000, fixed 200 → total 1200
      expect(policy.computeDiscountCents(10000)).toBe(1200);
    });

    it("each policy receives the original subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new PercentageDiscountPolicy(50)],
        "sum",
      );
      // 50%+50% of 1000 = 500+500 = 1000 (can exceed subtotal; Cart clamps)
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500)],
        "sum",
      );
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps negative individual results to 0 before summing", () => {
      const negativeMock = { computeDiscountCents: () => -100 };
      const policy = new CompositeDiscountPolicy(
        [negativeMock, new FixedAmountDiscountPolicy(300)],
        "sum",
      );
      // -100 clamped to 0, 300 stays → total 300
      expect(policy.computeDiscountCents(5000)).toBe(300);
    });

    it("defaults to sum mode when not specified", () => {
      const policy = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(policy.computeDiscountCents(10000)).toBe(1200);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new PercentageDiscountPolicy(50)],
        "chain",
      );
      // 50% of 1000 = 500, remaining 500; 50% of 500 = 250 → total 750
      expect(policy.computeDiscountCents(1000)).toBe(750);
    });

    it("ordering matters in chain mode", () => {
      const policyA = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(200), new PercentageDiscountPolicy(10)],
        "chain",
      );
      const policyB = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // A: fixed 200 off 1000 → remaining 800, 10% of 800 = 80 → total 280
      expect(policyA.computeDiscountCents(1000)).toBe(280);
      // B: 10% of 1000 = 100 → remaining 900, fixed 200 → total 300
      expect(policyB.computeDiscountCents(1000)).toBe(300);
    });

    it("stops compounding when remaining hits 0", () => {
      const policy = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(1000), new PercentageDiscountPolicy(50)],
        "chain",
      );
      // fixed 1000 on 500 → capped at 500, remaining 0, 50% of 0 → 0 → total 500
      expect(policy.computeDiscountCents(500)).toBe(500);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(policy.computeDiscountCents(0)).toBe(0);
    });
  });
});
"}

