    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("unknown", 5)).toThrow();
  });

  it("clear removes all items", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    cart.add(product("b", 2000), 2);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy (mutations don't affect cart)", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const snap = cart.snapshot();
    (snap as any)[0].quantity = 99;
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart — pricing pipeline", () => {
  it("subtotal is sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    cart.add(product("b", 500), 3);
    expect(cart.totals().subtotalCents).toBe(3500);
  });

  it("applies discount from injected policy", () => {
    const discount: DiscountPolicy = { computeDiscountCents: () => 500 };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(product("a", 2000), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(500);
    expect(t.totalCents).toBe(1500);
  });

  it("clamps discount to [0, subtotal]", () => {
    const overDiscount: DiscountPolicy = { computeDiscountCents: () => 99999 };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(product("a", 1000), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(1000);
    expect(t.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const negDiscount: DiscountPolicy = { computeDiscountCents: () => -500 };
    const cart = new Cart({ discountPolicy: negDiscount });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("tax is computed on discounted subtotal", () => {
    const discount: DiscountPolicy = { computeDiscountCents: () => 200 };
    const tax: TaxCalculator = {
      computeTaxCents: (taxable, _region) => Math.floor(taxable * 0.1),
    };
    const cart = new Cart({ discountPolicy: discount, taxCalculator: tax });
    cart.add(product("a", 1000), 1);
    // subtotal=1000, discount=200, discounted=800, tax=80
    const t = cart.totals();
    expect(t.taxCents).toBe(80);
  });

  it("shipping receives discounted subtotal", () => {
    const discount: DiscountPolicy = { computeDiscountCents: () => 500 };
    const shipping: ShippingCalculator = {
      computeShippingCents: (_lines, subtotalCents) =>
        subtotalCents >= 1000 ? 0 : 500,
    };
    const cart = new Cart({ discountPolicy: discount, shippingCalculator: shipping });
    cart.add(product("a", 1200), 1);
    // discounted = 700, which is < 1000, so shipping = 500
    expect(cart.totals().shippingCents).toBe(500);
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const discount: DiscountPolicy = { computeDiscountCents: () => 100 };
    const tax: TaxCalculator = { computeTaxCents: () => 50 };
    const shipping: ShippingCalculator = { computeShippingCents: () => 200 };
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
    });
    cart.add(product("a", 1000), 1);
    // subtotal=1000, discount=100, discounted=900, tax=50, ship=200
    // total = 900 + 50 + 200 = 1150
    const t = cart.totals();
    expect(t.totalCents).toBe(1150);
  });

  it("uses default region US", () => {
    let receivedRegion = "";
    const tax: TaxCalculator = {
      computeTaxCents: (_taxable, region) => {
        receivedRegion = region;
        return 0;
      },
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(product("a", 1000), 1);
    cart.totals();
    expect(receivedRegion).toBe("US");
  });

  it("uses custom region when configured", () => {
    let receivedRegion = "";
    const tax: TaxCalculator = {
      computeTaxCents: (_taxable, region) => {
        receivedRegion = region;
        return 0;
      },
    };
    const cart = new Cart({ taxCalculator: tax, region: "FR" });
    cart.add(product("a", 1000), 1);
    cart.totals();
    expect(receivedRegion).toBe("FR");
  });
});
"}

