import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it("returns 0 for a positive subtotal", () => {
    expect(policy.computeDiscountCents(10000)).toBe(0);
  });

  it("returns 0 for zero subtotal", () => {
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for a negative subtotal", () => {
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  it("rejects percent below 0", () => {
    expect(() => new PercentageDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("rejects percent above 100", () => {
    expect(() => new PercentageDiscountPolicy(101)).toThrow(RangeError);
  });

  it("rejects NaN", () => {
    expect(() => new PercentageDiscountPolicy(NaN)).toThrow(RangeError);
  });

  it("rejects Infinity", () => {
    expect(() => new PercentageDiscountPolicy(Infinity)).toThrow(RangeError);
  });

  it("accepts 0 percent and returns 0", () => {
    const policy = new PercentageDiscountPolicy(0);
    expect(policy.computeDiscountCents(10000)).toBe(0);
  });

  it("accepts 100 percent and returns full subtotal", () => {
    const policy = new PercentageDiscountPolicy(100);
    expect(policy.computeDiscountCents(10000)).toBe(10000);
  });

  it("computes 10% of 9999 rounded down", () => {
    const policy = new PercentageDiscountPolicy(10);
    expect(policy.computeDiscountCents(9999)).toBe(999);
  });

  it("computes 15% of 1000 exactly", () => {
    const policy = new PercentageDiscountPolicy(15);
    expect(policy.computeDiscountCents(1000)).toBe(150);
  });

  it("returns 0 when subtotal is 0", () => {
    const policy = new PercentageDiscountPolicy(50);
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 when subtotal is negative", () => {
    const policy = new PercentageDiscountPolicy(50);
    expect(policy.computeDiscountCents(-1000)).toBe(0);
  });

  it("floors fractional cents", () => {
    const policy = new PercentageDiscountPolicy(33);
    // 33% of 100 = 33.0 → 33
    expect(policy.computeDiscountCents(100)).toBe(33);
    // 33% of 101 = 33.33 → 33
    expect(policy.computeDiscountCents(101)).toBe(33);
  });
});

describe("FixedAmountDiscountPolicy", () => {
  it("rejects negative amountCents", () => {
    expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("rejects non-integer amountCents", () => {
    expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
  });

  it("accepts 0 and returns 0", () => {
    const policy = new FixedAmountDiscountPolicy(0);
    expect(policy.computeDiscountCents(5000)).toBe(0);
  });

  it("returns the full amount when subtotal exceeds it", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(10000)).toBe(500);
  });

  it("caps discount at subtotal when amount exceeds subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(5000);
    expect(policy.computeDiscountCents(3000)).toBe(3000);
  });

  it("returns 0 when subtotal is 0", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 when subtotal is negative", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(-100)).toBe(0);
  });
});

describe("CompositeDiscountPolicy", () => {
  it("rejects an empty policy list", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow(
      "CompositeDiscountPolicy requires at least one policy",
    );
  });

  describe("sum mode", () => {
    it("sums discounts from multiple policies", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 10000 = 1000, fixed 200 → total 1200
      expect(policy.computeDiscountCents(10000)).toBe(1200);
    });

    it("each policy receives the original subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new PercentageDiscountPolicy(50)],
        "sum",
      );
      // 50%+50% of 1000 = 500+500 = 1000 (can exceed subtotal; Cart clamps)
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500)],
        "sum",
      );
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps negative individual results to 0 before summing", () => {
      const negativeMock = { computeDiscountCents: () => -100 };
      const policy = new CompositeDiscountPolicy(
        [negativeMock, new FixedAmountDiscountPolicy(300)],
        "sum",
      );
      // -100 clamped to 0, 300 stays → total 300
      expect(policy.computeDiscountCents(5000)).toBe(300);
    });

    it("defaults to sum mode when not specified", () => {
      const policy = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(policy.computeDiscountCents(10000)).toBe(1200);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new PercentageDiscountPolicy(50)],
        "chain",
      );
      // 50% of 1000 = 500, remaining 500; 50% of 500 = 250 → total 750
      expect(policy.computeDiscountCents(1000)).toBe(750);
    });

    it("ordering matters in chain mode", () => {
      const policyA = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(200), new PercentageDiscountPolicy(10)],
        "chain",
      );
      const policyB = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // A: fixed 200 off 1000 → remaining 800, 10% of 800 = 80 → total 280
      expect(policyA.computeDiscountCents(1000)).toBe(280);
      // B: 10% of 1000 = 100 → remaining 900, fixed 200 → total 300
      expect(policyB.computeDiscountCents(1000)).toBe(300);
    });

    it("stops compounding when remaining hits 0", () => {
