toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  weightGrams: number | undefined,
  quantity: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for any lines", () => {
    expect(calc.computeShippingCents([makeLine("a", 500, 2)], 5000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  it("rejects negative flatCents", () => {
    expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
  });

  it("rejects non-integer flatCents", () => {
    expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
  });

  it("rejects negative freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
  });

  it("rejects non-integer freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new FlatShippingCalculator(500);
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });

  it("returns flat fee for non-empty cart", () => {
    const calc = new FlatShippingCalculator(799);
    expect(calc.computeShippingCents([makeLine("a", 100, 1)], 2000)).toBe(799);
  });

  it("returns 0 when subtotal meets freeOverCents threshold", () => {
    const calc = new FlatShippingCalculator(500, 5000);
    expect(calc.computeShippingCents([makeLine("a", 100, 1)], 5000)).toBe(0);
  });

  it("returns 0 when subtotal exceeds freeOverCents threshold", () => {
    const calc = new FlatShippingCalculator(500, 5000);
    expect(calc.computeShippingCents([makeLine("a", 100, 1)], 6000)).toBe(0);
  });

  it("returns flat fee when subtotal is below freeOverCents threshold", () => {
    const calc = new FlatShippingCalculator(500, 5000);
    expect(calc.computeShippingCents([makeLine("a", 100, 1)], 4999)).toBe(500);
  });

  it("accepts freeOverCents of 0 (always free for non-empty cart with non-negative subtotal)", () => {
    const calc = new FlatShippingCalculator(500, 0);
    expect(calc.computeShippingCents([makeLine("a", 100, 1)], 0)).toBe(0);
  });
});

describe("WeightBasedShippingCalculator", () => {
  it("rejects empty brackets", () => {
    expect(() => new WeightBasedShippingCalculator([])).toThrow(
      "at least one weight bracket is required",
    );
  });

  it("rejects bracket with non-positive upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 500 }]),
    ).toThrow(RangeError);
  });

  it("rejects bracket with negative costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
    ).toThrow(RangeError);
  });

  it("rejects negative overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 1000, costCents: 500 }],
          -1,
        ),
    ).toThrow(RangeError);
  });

  it("rejects non-integer overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 1000, costCents: 500 }],
          10.5,
        ),
    ).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([], 5000)).toBe(0);
  });

  it("returns 0 when total weight is 0 (no weightGrams)", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", undefined, 2)], 5000)).toBe(0);
  });

  it("selects the first bracket whose upToGrams >= weight", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ]);
    // 400g → first bracket
    expect(calc.computeShippingCents([makeLine("a", 400, 1)], 5000)).toBe(300);
    // 500g → first bracket (boundary)
    expect(calc.computeShippingCents([makeLine("a", 500, 1)], 5000)).toBe(300);
    // 501g → second bracket
    expect(calc.computeShippingCents([makeLine("a", 501, 1)], 5000)).toBe(600);
    // 1000g → second bracket (boundary)
    expect(calc.computeShippingCents([makeLine("a", 1000, 1)], 5000)).toBe(600);
    // 1001g → third bracket
    expect(calc.computeShippingCents([makeLine("a", 1001, 1)], 5000)).toBe(1200);
  });

  it("sorts brackets regardless of input order", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 5000, costCents: 1200 },
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 400, 1)], 5000)).toBe(300);
    expect(calc.computeShippingCents([makeLine("a", 900, 1)], 5000)).toBe(600);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ],
      2000,
    );
    expect(calc.computeShippingCents([makeLine("a", 1500, 1)], 5000)).toBe(2000);
  });

  it("falls back to heaviest bracket cost when no overflow specified", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 5000, 1)], 5000)).toBe(600);
  });

  it("sums weight across multiple lines", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 2000, costCents: 900 },
    ]);
    // 300*2 + 500*1 = 1100 → second bracket
    const lines: CartLine[] = [makeLine("a", 300, 2), makeLine("b", 500, 1)];
    expect(calc.computeShippingCents(lines, 5000)).toBe(900);
  });
});

